import Extend from 'flarum/common/extenders';
import User from 'flarum/common/models/User';
import VerificationRequest from './models/VerificationRequest';
export default [new Extend.Store().add('verification-requests', VerificationRequest), new Extend.Model(User).attribute('isVerified').attribute('verifiedAt', val => val ? new Date(val) : null).attribute('canRequestVerification').attribute('hasPendingVerificationRequest').attribute('isAvatarLocked')];